<div class="form-grid"><div><label for="name">Schedule name</label><input id="name" name="name" value="{{ old('name', $schedule?->name) }}" maxlength="255" required></div><div><label for="version">Version</label><input id="version" name="version" value="{{ old('version', $schedule?->version) }}" maxlength="40" required><span class="field-hint">Use the version label supplied by the responsible authority.</span></div></div>
<div class="form-grid"><div><label for="effective_from">Effective from</label><input id="effective_from" name="effective_from" type="date" value="{{ old('effective_from', $schedule?->effective_from?->format('Y-m-d')) }}"></div><div><label for="effective_until">Effective until</label><input id="effective_until" name="effective_until" type="date" value="{{ old('effective_until', $schedule?->effective_until?->format('Y-m-d')) }}"><span class="field-hint">Leave blank for an open-ended period.</span></div></div>
